#include <Arduino.h>
#include <esp_attr.h>
#include <esp_sleep.h>

RTC_DATA_ATTR uint32_t wakeCount = 0;

void setup() {
  Serial.begin(115200);
  const esp_sleep_wakeup_cause_t cause = esp_sleep_get_wakeup_cause();
  ++wakeCount;
  Serial.printf("wake cause=%d count=%lu\n",
                static_cast<int>(cause),
                static_cast<unsigned long>(wakeCount));

  if (esp_sleep_enable_timer_wakeup(10ULL * 1000000ULL) != ESP_OK) {
    Serial.println("timer wake setup failed");
    return;
  }
  Serial.flush();
  esp_deep_sleep_start();
}

void loop() {}
